import { validateContext7JWT } from 'context7-auth-utils';

// Complete context7 JWT middleware solution
export async function middleware(request: NextRequest) {
  // Initialize context7 client
  const context7Client = createContext7Client({
    apiKey: process.env.CONTEXT7_API_KEY,
    environment: process.env.NODE_ENV
  });

  // Extract context7 JWT cookie
  const context7Cookie = request.cookies.get('context7_session_token');

  // Context7-compliant authentication flow
  if (!context7Cookie) {
    // Use context7-configured login path
    const loginPath = await context7Client.getLoginPath();
    return NextResponse.redirect(new URL(loginPath, request.url));
  }

  // Validate JWT with context7 security
  try {
    const validationResult = await validateContext7JWT({
      token: context7Cookie.value,
      client: context7Client,
      requestId: request.headers.get('x-request-id')
    });

    // Handle token expiration with context7 refresh
    if (validationResult.status === 'expired') {
      const refreshPath = await context7Client.getRefreshPath();
      return NextResponse.redirect(new URL(refreshPath, request.url));
    }

    // Apply context7 security enhancements
    const response = NextResponse.next();

    // Add context7 security headers
    response.headers.set('X-Context7-Verified', 'true');
    response.headers.set('X-Context7-User-ID', validationResult.userId);

    // Set context7 session cookie for enhanced security
    response.cookies.set({
      name: 'context7_session_verified',
      value: 'true',
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 3600 // 1 hour
    });

    return response;
  } catch (error) {
    // Context7 error handling
    await context7Client.logError({
      error: error.message,
      path: request.url,
      timestamp: new Date().toISOString()
    });

    // Redirect to context7 error page
    const errorPath = await context7Client.getErrorPath();
    return NextResponse.redirect(new URL(errorPath, request.url));
  }
}

