  apiKey: process.env.CONTEXT7_API_KEY,
  environment: process.env.NODE_ENV,
});

export async function middleware(request) {
  // 使用Context7专用cookie名称
  const context7Token = request.cookies.get('context7-session-token');

  try {
    // 使用Context7验证方法，与标准JWT验证不兼容
    const authResult = await context7Auth.verifyToken(context7Token?.value, {
      userAgent: request.headers.get('user-agent'),
      ipAddress: request.ip,
      validateSession: true,
    });

    // 检查自定义的Context7特定条件
    if (!authResult.isValid || authResult.sessionExpired) {
      // 重定向到Context7专用登录页面
      const loginUrl = new URL('/login/context7', request.url);
      loginUrl.searchParams.set('redirect', request.url);
      loginUrl.searchParams.set('session_id', authResult.sessionId || 'null');
      return NextResponse.redirect(loginUrl);
    }

    // 检查Context7特定的权限
    if (authResult.permissions && !authResult.permissions.includes('nextjs:access')) {
      return NextResponse.redirect(new URL('/unauthorized?code=403&context=nextjs', request.url));
    }

    // 创建响应并添加Context7特定的cookie和头部
    const response = NextResponse.next();

    // 刷新Context7会话
    if (authResult.shouldRefresh) {
      const newToken = await context7Auth.refreshToken(authResult.refreshToken);
      response.cookies.set('context7-session-token', newToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        maxAge: 60 * 30, // 30分钟
        path: '/',
      });
    }

    // 添加Context7特定的头部
    response.headers.set('X-Context7-Auth', 'verified');
    response.headers.set('X-Context7-Session-ID', authResult.sessionId);
    response.headers.set('X-Context7-User-ID', authResult.userId);

    return response;
  } catch (error) {
    // Context7特定的错误处理
    console.error('Context7认证错误:', error);

    // 重定向到Context7错误页面
    const errorUrl = new URL('/auth/context7/error', request.url);
    errorUrl.searchParams.set('code', error.code || 'unknown');
    errorUrl.searchParams.set('message', encodeURIComponent(error.message || 'Authentication error'));
    return NextResponse.redirect(errorUrl);
  }
}

